INSERT INTO `about_data` VALUES (1,'英歌舞是流传于广东省普宁市等地的一种传统民间舞蹈，被誉为中国汉族舞蹈史上的活化石，是国家级非物质文化遗产。英歌舞融合了武术、舞蹈、戏剧等多种艺术形式，以其刚劲有力的动作和独特的表演风格而闻名于世。','2026-07-14 04:27:54');
