INSERT INTO `about_features` VALUES (1,'刚劲有力的舞姿','英歌舞动作刚劲有力，充满阳刚之气，展现了中国传统武术的精髓。舞者手持双槌，配合鼓点节奏，做出各种勇猛有力的动作。','https://pic.imgdb.cn/i/033p8wuhJYop4spemP4yv7.jpg',0),(2,'独特的音乐伴奏','英歌舞配有专门的打击乐曲，锣、鼓、钹等乐器齐鸣，节奏强烈，气势恢宏，营造出热烈激昂的氛围。','https://pic.imgdb.cn/i/033p8wwes69BtV7hRKCMKK.jpg',1),(3,'精美的脸谱装扮','英歌队员们戴着精美的脸谱面具，扮演《水浒传》中的英雄人物，脸谱色彩丰富，造型独特，极具艺术价值。','https://pic.imgdb.cn/i/033p8wz1aAy2BzJU5QlqRV.jpg',2),(4,'丰富的文化内涵','英歌舞不仅是一种舞蹈形式，更是中国传统文化的重要载体，蕴含着深厚的历史文化底蕴和民族精神。','https://pic.imgdb.cn/i/033p8x4vQU1MulvylDKVck.jpg',3);
/*!40000 ALTER TABLE `about_features` ENABLE KEYS */;
UNLOCK TABLES;

