INSERT INTO `actions` VALUES (1,'洗马','Xi Ma','模仿古代将士洗马的动作，双手持槌，身体左右摇摆，步伐稳健有力。','','https://pic.imgdb.cn/i/033p8yI0aUxmpif5qvdJAd.jpg','展现将士的豪迈气概',2),(2,'抛槌','Pao Chui','将双槌抛向空中，然后稳稳接住，动作惊险刺激，需要极高的技巧。','','https://pic.imgdb.cn/i/033p8yJTRCE2N29Nv73lGO.jpg','展示英歌队员的高超技艺',0),(3,'交叉','Jiao Cha','双槌在身前交叉舞动，动作快速有力，节奏感强。','','https://pic.imgdb.cn/i/033p8yKrVmlofxSzFobm6l.jpg','象征团结协作的精神',1),(4,'对打','Dui Da','两名队员面对面进行对打表演，模拟古代战场的战斗场景，动作逼真激烈。','','https://pic.imgdb.cn/i/033p8yST1cXmqbraUE6VZG.jpg','展现英雄的英勇无畏',3),(5,'飞跃','Fei Yue','队员高高跃起，在空中做出各种优美的动作，展现英歌的动感与美感。','','https://pic.imgdb.cn/i/033p8yTuVpxpwmDH8Zgm9U.jpg','象征积极向上的精神',4),(6,'盘龙','Pan Long','多名队员围成一圈，旋转舞动，如同盘龙一般，气势恢宏。','','https://pic.imgdb.cn/i/033p8yVVM8dKV5mqMM2psN.jpg','象征团结和力量',5);
