INSERT INTO `equipment_items` VALUES (1,1,'程咬金','绿色脸谱，代表勇猛鲁莽的性格','https://pic.imgdb.cn/i/033p8yWuVP5jzqs2Rn6Og6.jpg','程咬金是《水浒传》中的重要人物，以其勇猛无畏的性格著称。绿色脸谱通常代表勇猛、暴躁的性格特征。',2),(2,1,'秦琼','黄色脸谱，代表忠诚勇敢','https://pic.imgdb.cn/i/033p8yYXITJ8sVnnIkmUro.jpg','秦琼是唐代名将，也是《水浒传》中的英雄人物。黄色脸谱象征着忠诚、勇敢的品质。',1),(3,1,'尉迟恭','黑色脸谱，代表刚正不阿','https://pic.imgdb.cn/i/033p8yZpQUN6DTewcMBYVH.jpg','尉迟恭是唐代著名将领，以其刚正不阿的性格闻名。黑色脸谱通常代表正直、勇猛的人物。',2),(4,1,'鲁智深','蓝色脸谱，代表豪爽仗义','https://pic.imgdb.cn/i/033p8ybGiXEIJf0uYdcPDw.jpg','鲁智深是《水浒传》中的经典人物，以其豪爽仗义的性格深受人们喜爱。蓝色脸谱代表豪爽、勇猛的性格。',3),(5,2,'战衣','红色为主的传统战衣','https://pic.imgdb.cn/i/033p8ycnf66HQkSKrTuV2a.jpg','英歌队员穿着的战衣以红色为主，象征着英勇无畏的精神。战衣设计精美，装饰华丽。',4),(6,2,'战靴','黑色高筒战靴','https://pic.imgdb.cn/i/033p8ye4WitTfkC5yoNtyc.jpg','黑色高筒战靴是英歌队员的标准装备，既保护脚部，又增添了威武的气势。',5),(7,2,'腰带','金色宽腰带','https://pic.imgdb.cn/i/033p8yfQwaMVvmUmSOOkU6.jpg','金色宽腰带不仅是装饰，更是英歌表演中的重要道具，配合动作展现力量之美。',6),(8,3,'双槌','木质表演双槌','https://pic.imgdb.cn/i/033p8yhIMItI7GLn8hSxqe.jpg','双槌是英歌表演最核心的道具，通常由硬木制成，敲击时发出清脆的声响。',7),(9,3,'大鼓','大型战鼓','https://pic.imgdb.cn/i/033p8yixz0v8tiLTKPI8vQ.jpg','大鼓是英歌伴奏的核心乐器，鼓声雄浑有力，指挥着整个表演的节奏。',8),(10,3,'铜锣','青铜大锣','https://pic.imgdb.cn/i/033p8ylqZFuarDv5b3Au82.jpg','铜锣声音洪亮，穿透力强，是英歌表演中不可或缺的伴奏乐器。',9),(11,3,'海螺','海螺号角','https://pic.imgdb.cn/i/033p8ynqMc6OwKe0aKJAH4.jpg','海螺号角声音独特，常用于表演开始和高潮部分，增添了神秘的氛围。',10),(14,1,'黄诗培','hsp','https://pic.imgdb.cn/i/033pCM2u4zuaIQ9mGTWq4U.jpg','',12);
