INSERT INTO `mask_records` VALUES (2,'session_1784177522790_ckpw3qx','一张超写实摄影肖像作品，一位英俊的中国年轻男性，脸部精心绘制着英歌舞传统戏曲脸谱妆容。\n脸谱色彩搭配：米白、米白、米白、纯白、纯白、米白、米白、灰白、灰白、纯黑、热粉、纯黑、米白、米白、#E0E0E0、#E0E0E0、米白、灰白、灰白、大红、#E0E0E0等传统戏曲色彩。\n具体区域配色：左额头: 米白, 右额头: 米白, 鼻梁: 米白, 左眼: 纯白, 右眼: 纯白, 左脸颊: 米白, 右脸颊: 米白, 左脸下部: 灰白, 右脸下部: 灰白, 鼻子: 纯黑, 眼周: 热粉, 瞳孔: 纯黑, 左下颌: 米白, 右下颌: 米白, 左耳: #E0E0E0, 右耳: #E0E0E0, 下巴: 米白, 左下巴: 灰白, 右下巴: 灰白, 下唇: 大红, 下巴尖: #E0E0E0。\n脸谱风格：白脸奸诈，融合广东潮汕英歌舞的非遗传统文化特色。\n妆容特征：脸部底色为米白色，眉眼用黑色或金色勾勒，额头和脸颊有对称的传统图案纹样，线条粗犷有力，色彩饱和浓郁。\n摄影要求：专业影棚灯光，柔和均匀的补光，面部细节清晰可见，皮肤质感真实，8K超高清画质，浅景深，背景为素雅的深色或灰色，突出人物主体。\n人物表情：自信坚毅，目光炯炯，正面直视镜头，气质英武。\n文化标签：非物质文化遗产、潮汕英歌舞、中国传统文化、传统戏曲艺术。','https://ark-acg-cn-beijing.tos-cn-beijing.[REDACTED]/doubao-seedream-5-0-pro/484758d5be134efd2cf8bf06c27582a61c0a8c636387771487120/Image/2123996397/021784177783636c8a0c16a28572c60fb8fc2dfe431eb5d857484.jpeg?X-Tos-Algorithm=TOS4-HMAC-SHA256&X-Tos-Credential=[REDACTED]%2F20260716%2Fcn-beijing%2Ftos%2Frequest&X-Tos-Date=20260716T045819Z&X-Tos-Expires=86400&X-Tos-Signature=adc2e937ee661fcc43320649c9b3e30d9e71869f83571fca77c2534d3c940ee0&X-Tos-SignedHeaders=host','<svg xmlns=\"http://www.w3.org/2000/svg\" trae-inspector-start-line=\"410\" trae-inspector-start-column=\"16\" trae-inspector-end-line=\"453\" trae-inspector-end-column=\"22\" trae-inspector-file-path=\"src\\\\pages\\\\MaskDIY.tsx\" trae-inspector-static-props=\"%7B%22cwd%22%3A%22C%3A%5C%5CUsers%5C%5CY90000P%5C%5CDesktop%5C%5C%E4%B8%89%E4%B8%8B%E4%B9%A1%22%7D\" viewBox=\"0 0 1054 1260\" class=\"w-full h-auto\" style=\"filter: drop-shadow(rgba(0, 0, 0, 0.18) 0px 8px 24px); max-height: 600px;\"><defs trae-inspector-start-line=\"411\" trae-inspector-start-column=\"18\" trae-inspector-end-line=\"413\" trae-inspector-end-column=\"25\" trae-inspector-file-path=\"src\\\\pages\\\\MaskDIY.tsx\" trae-inspector-static-props=\"%7B%22cwd%22%3A%22C%3A%5C%5CUsers%5C%5CY90000P%5C%5CDesktop%5C%5C%E4%B8%89%E4%B8%8B%E4%B9%A1%22%7D\"><g trae-inspector-start-line=\"412\" trae-inspector-start-column=\"49\" tra