--
-- Table structure for table `people`
--

DROP TABLE IF EXISTS `people`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `people` (
  `id` int NOT NULL AUTO_INCREMENT,
  `category_id` int NOT NULL,
  `name` varchar(100) NOT NULL,
  `role` varchar(255) DEFAULT NULL,
  `avatar` varchar(500) DEFAULT NULL,
  `story` text,
  `achievements` text,
  `sort_order` int DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `category_id` (`category_id`),
  CONSTRAINT `people_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `people_categories` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `people`
--

LOCK TABLES `people` WRITE;
/*!40000 ALTER TABLE `people` DISABLE KEYS */;
INSERT INTO `people` VALUES (1,1,'陈英辉','国家级非物质文化遗产传承人','https://pic.imgdb.cn/i/033p8ypAFWirLKRQvS2jC4.jpg','陈英辉大师是普宁英歌的杰出代表，从少年时期开始学习英歌，至今已有60多年的表演经验。他不仅技艺精湛，更致力于英歌文化的传承和推广，培养了大批优秀的英歌队员。','[\"国家级非物质文化遗产传承人\",\"广东省民间文化杰出传承人\",\"多次获得省级以上文艺奖项\"]',0),(2,1,'李炳炎','国家级非物质文化遗产传承人','https://pic.imgdb.cn/i/033p8yqMQs80HTfBoeOmv3.jpg','李炳炎大师出生于英歌世家，自幼跟随父辈学习英歌。他精通多种英歌流派，尤其擅长脸谱绘制和动作编排，为英歌文化的发展做出了重要贡献。','[\"国家级非物质文化遗产传承人\",\"潮汕文化名人\",\"英歌脸谱艺术大师\"]',1),(3,2,'张锦雄','省级非物质文化遗产传承人','https://pic.imgdb.cn/i/033p8yrprbyffZ7e3nICpd.jpg','张锦雄是新坛英歌队的主教练，从事英歌教学工作30余年。他注重培养年轻队员，将传统英歌技艺与现代教学方法相结合，取得了显著成效。','[\"广东省非物质文化遗产传承人\",\"普宁市英歌协会副会长\",\"多次带领队伍获得省级奖项\"]',2),(4,2,'王秋生','省级非物质文化遗产传承人','https://pic.imgdb.cn/i/033p8yt7tpgvnD828MYNkJ.jpg','王秋生是泥沟英歌队的核心成员，擅长英歌的阵法编排和音乐创作。他创作的多个英歌节目在省级比赛中获奖，为英歌艺术的创新发展做出了贡献。','[\"广东省非物质文化遗产传承人\",\"揭阳市优秀民间艺人\",\"英歌节目创作奖\"]',3),(5,3,'陈明轩','青年英歌队员','https://pic.imgdb.cn/i/033p8yuK4txKcVGLGyUS0m.jpg','陈明轩从小热爱英歌，10岁开始学习，如今已是新坛英歌队的骨干队员。他不仅继承了传统技艺，还积极参与英歌文化的推广活动，是新一代传承人的优秀代表。','[\"广东省青少年才艺大赛一等奖\",\"普宁英歌新秀奖\",\"多次参与大型演出\"]',4),(6,3,'林小雨','青年英歌队员','https://pic.imgdb.cn/i/033p8yvczGPgevFDigEQTD.jpg','林小雨是近年来涌现的优秀女英歌队员，她打破了传统观念的束缚，成为英歌队中的一道亮丽风景线。她的表演刚柔并济，深受观众喜爱。','[\"揭阳市青年英歌比赛金奖\",\"普宁英歌最佳新人奖\",\"网络人气奖\"]',5);
/*!40000 ALTER TABLE `people` ENABLE KEYS */;
UNLOCK TABLES;

