/*!40000 ALTER TABLE `people_categories` DISABLE KEYS */;
INSERT INTO `people_categories` VALUES (1,'国家级传承人','获得国家级非物质文化遗产传承人名誉的英歌大师',1),(2,'省级传承人','获得省级非物质文化遗产传承人名誉的英歌专家',1),(3,'青年传承人','新一代英歌传承者，肩负着传承和创新的使命',2);
/*!40000 ALTER TABLE `people_categories` ENABLE KEYS */;
UNLOCK TABLES;

