INSERT INTO `xintan_stories` VALUES (4,'国家级非物质文化遗产','2006年，普宁英歌被国务院列入第一批国家级非物质文化遗产名录。新坛英歌当时为普宁市申请非遗专题片提供了大量视频素材，为普宁英歌的非遗申报作出了重要贡献。2018年11月，揭阳市文化广电新闻出版局授牌揭阳市非物质文化遗产传承基地——普宁市新坛英歌队（普宁英歌）。','',0),(5,'市级代表性传承人——陈进勇','2017年10月，新坛英歌队教练陈进勇被揭阳市文化广电新闻出版局命名为市级非物质文化遗产项目《英歌（普宁英歌）》的代表性传承人。陈进勇教练长期致力于新坛英歌的传承与发展，培养了一批又一批英歌后辈。','',1),(6,'南枝拳融入英歌舞','19世纪下半叶，武师陈南枝入普宁设馆授徒，最初选定新坛村。随着南枝拳的套路步法在该村村民中传播，其精髓韵味便逐渐融入新坛村的英歌舞，使新坛英歌舞姿南拳步法明显，剽悍威武，气势雄浑，独树一帜，成为普宁市快板英歌的代表之一。','',2),(7,'头槌李逵的浴布花','新坛英歌队头槌\"李逵\"头上的装扮颇具特色，用潮汕地区的浴布（洗衣巾）打成浴布花。这一独特的装扮既是潮汕民间文化的体现，也成为新坛英歌区别于其他英歌队的标志性特征。','',3),(8,'《新坛英歌》图文集与VCD','2003年，新坛村委会成立新坛英歌编委会，采访英歌老艺人，编印了《新坛英歌》图文集和拍摄制作《新坛英歌舞》VCD片，系统记录和保存了新坛英歌的历史与技艺。','',4),(9,'纪录片《英雄的舞蹈》','2015年，深圳世纪华业投资有限公司携手深圳电视台联合摄制大型系列纪录片《非常遗产》，摄制组走进新坛村，拍摄新坛英歌的化妆、表演以及非物质文化遗产的传承等等，制作纪录片《英雄的舞蹈》，让新坛英歌走向更广阔的舞台。','',5),(10,'英歌画面登上个性化邮票','新坛英歌表演的画面两次被印上\"岭南水城——揭阳\"、\"岭南水城揭阳印象\"个性化邮票，成为揭阳城市文化名片的重要组成部分，也见证了新坛英歌的艺术价值和文化影响力。','',6),(11,'中泰英歌联合巡演','2025年11月8日，新坛英歌队与泰国春武里府文益英歌、池尾上寮英歌共同举行\"英歌战舞·舞动四海\"——普宁国际商品城中泰英歌联合巡演活动。中泰英歌队同台竞技，展现了英歌文化在海外的传承与发展，促进了中泰文化交流。','',7),(12,'英歌走进军营','2025年6月8日，新坛英歌队走进军营——到普宁英歌山部队教导团为官兵表演，并于当晚参加揭阳某部队\"逐梦深蓝 扬帆起航\"2025年度上半年新兵结业晚会。英歌舞的阳刚之气与军人的铁血精神交相辉映。','',8),(13,'群星奖金奖','2007年9月，经过层层严格筛选，新坛英歌节目入选国家文化部第十四届\"群星奖\"决赛，又应邀参加\"2007年广东省国际旅游文化节\"开幕式演出，以创新灵活多变的动作套式、威风飒爽的阵势获得较高的声誉。','',9),(14,'首届广东社区文化节金奖','2011年7月15日，新坛英歌队参加首届广东社区文化节\"岭南风情\"全省农民文艺大汇演，以技巧活、气势壮的精湛表演征服了评委和专家，摘取金奖。这是新坛英歌在省级舞台上获得的重要荣誉。','',10);
/*!40000 ALTER TABLE `xintan_stories` ENABLE KEYS */;
UNLOCK TABLES;

