INSERT INTO `xintan_team` VALUES (1,'新坛英歌队','约清朝嘉庆年间（二百多年历史）','新坛英歌为普宁市快板英歌代表之一，群众基础非常广泛。新坛英歌特色鲜明，其鼓点密集，突出\"劲\"字，讲究击槌重力，出槌收槌利索；旋槌有花，上旋下击，槌步紧扣自如。新坛英歌队继承传统，并不断发展创新，将传统的英歌舞表演动作、槌法、阵势、音乐等融入现代舞蹈节奏、舞台表演元素和艺术理念，使新坛英歌既保留传统精华，又具有英姿勃发的时代特色；既适合广场表演，也适应舞台上演出。新坛英歌队头槌\"李逵\"头上的装扮颇具特色，用潮汕地区的浴布（洗衣巾）打成浴布花。普宁英歌于2006年被国务院列入第一批国家级非物质文化遗产名录，新坛英歌当时为普宁市申请非遗专题片提供了大量视频素材。','[\"https://pic.imgdb.cn/i/033p8xWr3yLRlXkji3S4xa.jpg\",\"https://pic.imgdb.cn/i/033p8xfrcbV5I0laNhGJ9p.jpg\",\"https://pic.imgdb.cn/i/033p8xjQVq3UvlsQzNzhM9.jpg\"]','2026-07-14 07:01:11');
/*!40000 ALTER TABLE `xintan_team` ENABLE KEYS */;
UNLOCK TABLES;

