INSERT INTO `xintan_team_achievements` VALUES (4,'2026年1月2日 参加\"看英歌 到揭阳\"普宁分会场第30场活动——2026年普宁市流沙广场元旦英歌大汇演',0),(5,'2025年12月31日 参加普宁国际商品城尚东新天地首届抖音生活跨年季暨6周年庆典，与香港艺人林晓峰同台',1),(6,'2025年11月8日 新坛与泰国春武里府文益英歌、池尾上寮英歌举行\"英歌战舞·舞动四海\"——普宁国际商品城中泰英歌联合巡演',2),(7,'2025年7月16日 配合广东工业大学\"潮这走\"广东青年大学生\"百千万工程\"突击队调研拍摄、推广英歌舞文化',3),(8,'2025年7月5日 参加在流沙广场举办的\"看英歌 到揭阳\"（普宁分会场）特色文化活动',4),(9,'2025年6月8日 英歌舞走进军营——到普宁英歌山部队教导团为官兵表演，并参加揭阳某部队\"逐梦深蓝 扬帆起航\"2025年度上半年新兵结业晚会',5),(10,'2025年3月13日 参加普宁市2025年上半年欢送新兵游街及\"青春献国防 热血铸军魂\"欢送新兵晚会',6),(11,'2024年7月29日 配合深圳大学大学生\"百千万工程\"突击队调研拍摄、推广英歌舞文化',7),(12,'2024年7月12日 配合广东工业大学\"潮这走\"广东青年大学生\"百千万工程\"突击队调研拍摄、推广英歌舞文化',8),(13,'2024-2025年 多次应邀到广州、佛山等地表演',9),(14,'2018年11月 揭阳市文化广电新闻出版局授牌揭阳市非物质文化遗产传承基地——普宁市新坛英歌队（普宁英歌）',10),(15,'2017年10月 英歌队教练陈进勇被命名为市级非物质文化遗产项目《英歌（普宁英歌）》代表性传承人',11),(16,'2012年9月28日 参加在揭阳楼广场举办的\"幸福揭阳——乡乡乐起来\"群众文化活动汇演',12),(17,'2012年9月21日 参加首届\"普宁幸福活动周\"启动仪式暨\"幸福普宁 康美之约 庆国庆\"文艺晚会',13),(18,'2012年1月18日 参加\"春的绽放——广东省2012年春节军民联欢晚会\"（广州友谊剧院）',14),(19,'2011年8月19日 参加首届广东社区文化节闭幕式广场舞演（广州市海珠区大元帅府前广场）',15),(20,'2011年7月15日 参加首届广东社区文化节\"岭南风情\"全省农民文艺大汇演，摘取金奖',16),(21,'2007年9月 入选国家文化部第十四届\"群星奖\"决赛，应邀参加\"2007年广东省国际旅游文化节\"开幕式演出',17),(22,'2006年 普宁英歌列入第一批国家级非物质文化遗产名录，新坛英歌提供大量视频素材',18);
