INSERT INTO `xintan_training` VALUES (1,'新坛英歌群众基础非常广泛，村内常年培训青少年英歌舞。近年来，新坛英歌除了在村内培训青少年英歌舞，也让英歌舞走进校园：2019年开始在新坛小学培训少儿英歌，让英歌文化从娃娃抓起。2025年在普宁国际商品城开展英歌进商城活动，每周六晚表演英歌舞，使英歌舞更广泛得到传承。新坛英歌队还积极与高校合作，配合广东工业大学、深圳大学等高校的\"百千万工程\"突击队开展调研拍摄，共同推广英歌舞文化。','[\"https://pic.imgdb.cn/i/033p8xolMRs61T3l7DSO5W.jpg\",\"https://pic.imgdb.cn/i/033p8xwMNlQ7qbky4b3DiL.jpg\",\"https://pic.imgdb.cn/i/033p8xy34hErc22Nz4xSdT.jpg\"]','2026-07-14 07:01:11');
/*!40000 ALTER TABLE `xintan_training` ENABLE KEYS */;
