LOCK TABLES `xintan_village` WRITE;
/*!40000 ALTER TABLE `xintan_village` DISABLE KEYS */;
INSERT INTO `xintan_village` VALUES (1,'新坛村','英歌舞的起源，\"英歌\"又称\"秧歌\"、\"莺歌\"，广泛流传于潮汕各地，尤其在普宁、潮阳等地更是盛行。英歌舞在流传的过程中得到不断的创新发展。英歌主要在春节和元宵期间活动，遇有盛大庆典或其他喜庆节日也必参加。英歌表演的是《水浒传》中梁山泊众英雄乔装打扮攻打大名府，营救卢俊义的故事，但表现手法富于写意性，既不叙述故事情节也不表现人物，更多的是渲染战斗情景和热烈气氛，塑造英雄群体的形象，通过人物造型、服饰道具、形体动态、音响节奏等艺术处理，从整体上体现出男性粗犷雄浑的阳刚之美。','关于英歌舞的由来，历来有几种说法：傩舞说——据学者研究，英歌舞可能由祭神活动的古代傩舞演变而来；戏曲说——相传源于外江戏《梁山泊攻打大名府》剧目；练武习艺说——相传源于农民为反抗欺压而练武习艺。舞英歌，潮汕民间也叫\"茂英歌\"、\"扣英歌\"，也有\"唱英歌\"的说法。\"茂\"是\"舞\"的方言化俗称，且\"茂\"本是草木繁盛之意，含有借助英歌槌来表现强烈的节奏和热烈的气氛。\"扣\"是扣打，即扣打英歌槌，边行进边跳舞。\"唱\"英歌意味着边舞边唱，不只是单纯地击棒起舞。目前潮汕英歌基本上是只舞不唱，且唱且舞的英歌在历史沿革过程中几乎消失了。新坛英歌舞约有二百多年历史，为普宁市快板英歌代表之一。19世纪下半叶，武师陈南枝入普宁设馆授徒，最初选定新坛村。随着南枝拳的套路步法在该村村民中传播，其精髓韵味便逐渐融入新坛村的英歌舞，使舞姿南拳步法明显，剽悍威武，气势雄浑，独树一帜。','https://pic.imgdb.cn/i/033p8xGFBethbPTexoa69K.jpg','2026-07-14 07:01:11','23.30','116.18','广东省揭阳市普宁市流沙东街道新坛村','新坛村位于广东省东南部、揭阳市普宁市流沙东街道，地处榕江流域中下游平原地带，地势平坦开阔，土壤肥沃，是典型的潮汕平原村落。','新坛村所在的潮汕地区依山傍海，北靠大南山余脉，南临南海，四季常青。村落周边河网密布，水系发达，既有传统潮汕民居群落，又有现代村镇风貌，人文与自然景观交融。','属亚热带季风气候，年平均气温约 21°C，雨量充沛，光照充足，气候温和湿润，适宜农耕与各类民俗活动的开展。','交通便利，靠近国道和省道，距揭阳市中心约 30 公里，距普宁市中心仅数公里，周边有多条公交线路经过，便于游客前往参观体验。');
/*!40000 ALTER TABLE `xintan_village` ENABLE KEYS */;
UNLOCK TABLES;
